function nav(){ renderPrimaryCandidates();renderCandidatePanelContext(); $('candidateTree').innerHTML=state.tabs.filter(t=>!t.parentId&&(!state.candidateFamily||state.candidateFamily===t.id)).map(t=>{const cs=children(t.id);return`<div class="family">${rowHTML(t)}${cs.length?`<button class="family-toggle" data-collapse="${t.id}">${state.collapsed.has(t.id)?'▸':'▾'} 遅延 ${cs.length}件</button><div ${state.collapsed.has(t.id)?'hidden':''}>${cs.map(rowHTML).join('')}</div>`:''}</div>`;}).join('');$('groupList').innerHTML=state.groups.map(g=>`<div class="group-row ${g.id===state.active?'active':''}"><button data-group="${g.id}">${g.id} ${esc(g.name)}${g.members.length<2?'（不足）':''}</button><button data-group-menu="${g.id}" aria-label="${g.id} の操作">…</button></div>`).join('');$$('[data-tab]').forEach(b=>b.onclick=()=>{if(state.chooser){toggleChoice(b.dataset.tab);return;}const filter=state.candidateFamily;choose(b.dataset.tab);setCandidateManager(true,filter);});$$('[data-visible]').forEach(x=>x.onchange=()=>setCaseVisibility(x.dataset.visible,x.checked));$$('[data-select-case]').forEach(x=>x.onchange=()=>toggleChoice(x.dataset.selectCase));$$('[data-collapse]').forEach(b=>b.onclick=()=>{state.collapsed.has(b.dataset.collapse)?state.collapsed.delete(b.dataset.collapse):state.collapsed.add(b.dataset.collapse);nav();});$$('[data-group]').forEach(b=>b.onclick=()=>choose(b.dataset.group));$$('[data-case-menu]').forEach(b=>b.onclick=e=>caseMenu(b.dataset.caseMenu,e));$$('[data-row]').forEach(row=>row.oncontextmenu=e=>{e.preventDefault();caseMenu(row.dataset.row,e);});$$('[data-group-menu]').forEach(b=>b.onclick=e=>groupMenu(b.dataset.groupMenu,e));$('groupPicker').hidden=!state.chooser;if(state.chooser){$('groupPickerTitle').textContent=state.chooser.gid?'比較対象を変更':'比較する候補を選択';$('commitGroup').disabled=state.chooser.ids.length<2;}}
function levelOptions(value){return state.levels.map(l=>`<option value="${l.id}" ${l.id===value?'selected':''}>${esc(l.name)}</option>`).join('');}
function renderLayers(){ $('layerList').innerHTML=state.layerSets.map(l=>{const ids=new Set(l.regions.map(r=>r.levelId||'normal')),selected=ids.size===1?[...ids][0]:'';return `<div class="layer-entry"><div class="layer-row" data-layer-row="${l.id}"><input type="checkbox" data-layer-visible="${l.id}" ${l.visible?'checked':''} aria-label="${esc(l.name)} を描画"><span class="layer-name">${esc(l.name)} <small>${l.regions.length}領域</small></span><select data-layer-level="${l.id}" aria-label="${esc(l.name)} 全領域のレベル">${selected?'':'<option value="">混在</option>'}${levelOptions(selected)}</select><button data-layer-menu="${l.id}" aria-label="${esc(l.name)} の操作">…</button></div>${l.regions.length>1?`<details class="region-levels"><summary>領域ごとに分類</summary>${l.regions.map(r=>`<label>${esc(r.name)}<select data-region-level="${l.id}/${r.id}">${levelOptions(r.levelId||'normal')}</select></label>`).join('')}</details>`:''}</div>`;}).join('')||'<p class="muted">未設定 · ファイルを追加して着地点との干渉を評価します。</p>';$('zoneSummary').textContent=state.layerSets.length?`禁止領域 ${state.layerSets.length}ファイル · 版${state.zoneVersion}`:'禁止領域 未設定';$$('[data-layer-visible]').forEach(x=>x.onchange=()=>{state.layerSets.find(l=>l.id===x.dataset.layerVisible).visible=x.checked;drawMap();});$$('[data-layer-level]').forEach(x=>x.onchange=()=>{if(!x.value)return;state.layerSets.find(l=>l.id===x.dataset.layerLevel).regions.forEach(r=>r.levelId=x.value);refresh();});$$('[data-region-level]').forEach(x=>x.onchange=()=>{const[lid,rid]=x.dataset.regionLevel.split('/');state.layerSets.find(l=>l.id===lid).regions.find(r=>r.id===rid).levelId=x.value;refresh();});$$('[data-layer-menu]').forEach(b=>b.onclick=e=>layerMenu(b.dataset.layerMenu,e));$('saveZones').disabled=!state.layerSets.length;}
function editFamilyColor(id){const t=tab(id),p=t.parentId?tab(t.parentId):t;BJP_APPEARANCE.family(p,color=>{p.color=color;children(p.id).forEach(c=>c.color=color);refresh();});}
function zonePresentation(){return state.layerSets.flatMap(l=>l.regions.map(r=>({id:l.id+'-'+r.id,name:BJP_STYLE.regionLabel(l.name,r.name),visible:l.visible,polygons:r.polygons,level:BJP_STYLE.levelFor(r,state.levels)})));}
function updateBandLegend(){const t=activeTab();if(bridge.real&&bridge.historical&&!t?.result){$('bandLegend').textContent=realModeCopy(true,state.tabs).emptyLegend;return;}if(t?.result?.kind==='ensemble'){const a=analysisFor(t);$('bandLegend').textContent=!a?'経験域の共通分析を読込中':a.landing.rank===null?'着地なし · 経験域なし':a.landing.rank===0?'全着地点が同一点 · 50/90/95%を点で表示（面積を付けません）':a.landing.rank===1?'着地点は一直線 · 50/90/95%を線で表示（幅を付けません）':'濃い面から50%内 / 50–90%間 / 90–95%間。実含有数は分母欄へ。';return;}$('bandLegend').innerHTML=t&&t.visible?'<b>注目 '+esc(t.id)+'</b> '+BJP_STYLE.bandLevels.map((p,i)=>`<span class="band-key ${state.bands.includes(p)?'':'band-off'}"><i style="background:${seriesColor(t)};opacity:${[.24,.13,.065][i]}"></i>${i?BJP_STYLE.bandLevels[i-1]*100+'–':''}${p*100}%${i?'間':'内'}</span>`).join(''):'帯なし · 注目候補が非表示、または履歴比較を選択中';}
$('editLevels').onclick=()=>BJP_APPEARANCE.levels(state.levels,levels=>{state.levels=levels;refresh();});
$('editTheme').onclick=()=>{if(activeTab())editFamilyColor(state.active);};
function menu(e,items){e.stopPropagation();const el=$('objectMenu');el.innerHTML=items.map((x,i)=>`<button data-action="${i}" class="${x.danger?'danger':''}" ${x.disabled?'disabled':''}>${esc(x.text)}</button>`).join('');el.hidden=false;const rect=e.currentTarget?.getBoundingClientRect?.(),x=e.type==='contextmenu'?e.clientX:rect?.right||e.clientX,y=e.type==='contextmenu'?e.clientY:rect?.top||e.clientY;el.style.left=Math.min(Math.max(6,x),innerWidth-210)+'px';el.style.top=Math.min(Math.max(6,y),innerHeight-items.length*37-12)+'px';el.querySelectorAll('button').forEach((b,i)=>b.onclick=()=>{el.hidden=true;items[i].fn();});}
function caseMenu(id,e){const t=tab(id);menu(e,[...(!bridge.historical&&t.draft.model!=='season'?[{text:t.parentId?'親 '+t.parentId+' の遅延列を編集':children(t.id).length?'遅延列を編集':'遅延列を作る',fn:()=>openDelays(t.id)}]:[]),{text:'系列のテーマ色',fn:()=>editFamilyColor(t.id)},{text:'条件を複製',fn:()=>{if(bridge.real){bridge.action('duplicate',{id});return;}const c=newCase(t.draft,t.name+' の比較案',null,dirty(t)?null:t.result);choose(c.id);}},{text:'比較グループへ追加',disabled:!t.result,fn:()=>addToGroup(id)},...(t.parentId?[{text:'独立した候補にする',fn:()=>detach(id)}]:[]),{text:'候補を削除',danger:true,fn:()=>removeCase(id)}]);}
function groupMenu(id,e){menu(e,[{text:'比較対象を変更',fn:()=>startGroup(id)},{text:'比較を削除',danger:true,fn:()=>{state.groups=state.groups.filter(g=>g.id!==id);if(state.active===id)state.active=state.tabs[0]?.id||'';refresh();}}]);}
function layerMenu(id,e){const l=state.layerSets.find(l=>l.id===id);menu(e,[{text:'名称を変更',fn:()=>showDialog('領域セットの名称',`<label>表示名<input id="newLayerName" value="${esc(l.name)}" maxlength="80"></label>`,()=>{l.name=$('newLayerName').value.trim()||l.name;renderLayers();drawMap();})},{text:'この領域セットを削除',danger:true,fn:()=>{state.layerSets=state.layerSets.filter(x=>x.id!==id);state.zoneVersion++;refresh();}}]);}
function showDialog(title,body,fn,label='適用'){ $('dialogTitle').textContent=title;$('dialogBody').innerHTML=body;$('dialogApply').textContent=label;dialogAction=fn;$('actionDialog').showModal();}
$('dialogCancel').onclick=()=>$('actionDialog').close();$('dialogApply').onclick=()=>{const fn=dialogAction;$('actionDialog').close();fn?.();};document.addEventListener('click',e=>{if(!$('objectMenu').contains(e.target))$('objectMenu').hidden=true;});
function affectedGroups(ids){return state.groups.filter(g=>g.members.some(id=>ids.includes(id)));}
function snapshotRemoval(){state.undo={tabs:state.tabs.map(t=>({...t,draft:copy(t.draft),results:[...t.results]})),groups:copy(state.groups),active:state.active};}
function removeIds(ids){if(bridge.real){bridge.action('remove',{ids});return;}snapshotRemoval();state.tabs=state.tabs.filter(t=>!ids.includes(t.id));for(const g of state.groups)g.members=g.members.filter(id=>!ids.includes(id));if(ids.includes(state.active))state.active=state.tabs[0]?.id||'';for(const key of Object.keys(state.delayEdits))delete state.delayEdits[key];refresh();notify(`${ids.length}候補を外しました。保存済み計算結果は保持。`,true);}
function undoRemoval(){if(!state.undo)return;Object.assign(state,state.undo);state.undo=null;refresh();notify('候補と比較所属を元に戻しました。');}
function removeCase(id){const ids=[id,...children(id).map(t=>t.id)],gs=affectedGroups(ids);showDialog('候補を削除',`<p>${ids.map(esc).join('・')}を候補一覧から外します。${children(id).length?'従属する遅延子も含みます。':''}</p><p>${gs.length?'影響する比較群：'+gs.map(g=>esc(g.id)+'（'+g.members.filter(x=>ids.includes(x)).map(esc).join('・')+'を除く）').join('、'):'比較群への影響はありません。'}</p><p class="muted">${bridge.real?'固定計算結果は保持します。この画面では候補削除の即時取消は未接続です。':'計算結果のキャッシュは消さず、直後に元に戻せます。'}</p>`,()=>removeIds(ids),'削除');}
function detach(id){if(bridge.real){bridge.action('detach',{id});return;}const t=tab(id),p=t.parentId;if(!p)return;t.draft=draftFor(t);delete t.parentId;delete t.delay;t.name+='（独立）';delete state.delayEdits[p];refresh();notify('独立した候補へ変更。結果・比較所属は保持しました。');}
function startGroup(gid=null){setCandidateManager(true);state.chooser={gid,ids:gid?[...group(gid).members]:activeTab()?.result?[state.active]:[]};nav();}
function toggleChoice(id){if(!tab(id)?.result)return;const ids=state.chooser.ids;state.chooser.ids=ids.includes(id)?ids.filter(x=>x!==id):[...ids,id];nav();}
function addToGroup(id){if(!state.groups.length){startGroup();state.chooser.ids=[id];nav();return;}showDialog('比較グループへ追加',state.groups.map(g=>`<label><input type="checkbox" data-membership="${g.id}" ${g.members.includes(id)?'checked':''}>${esc(g.id+' '+g.name)}</label>`).join(''),()=>{const desired=$$('[data-membership]:checked').map(x=>x.dataset.membership);for(const g of state.groups){g.members=g.members.filter(x=>x!==id);if(desired.includes(g.id))g.members.push(id);}refresh();});}
$('newGroup').onclick=()=>startGroup();$('editGroup').onclick=()=>startGroup(state.active);$('cancelGroup').onclick=()=>{state.chooser=null;nav();};$('commitGroup').onclick=()=>{if(state.chooser.ids.length<2)return;const c=state.chooser,g=c.gid?group(c.gid):{id:'G'+nextGroup++,name:'',nameMode:'auto',members:[]};g.members=[...c.ids];if(!c.gid)state.groups.push(g);state.chooser=null;choose(g.id);};
function choose(id){if(!tab(id)&&!group(id))return;setInputShelf(false);setCandidateManager(false);cancelLocation();clearDrawing();state.active=id;state.detail=false;state.chooser=null;$('runMessage').textContent='';refresh();}
function syncChildren(parent){for(const child of children(parent.id))child.draft=draftFor(child);}
function commitResults(ts){let reused=0,computed=0;for(const t of ts){t.draft=draftFor(t);const key=cacheKey(t.draft);resultCache.has(key)?reused++:computed++;t.result=resultFor(t.draft);if(!t.results.includes(t.result))t.results.push(t.result);}return{reused,computed};}
function delayPlan(p){const df=delayDiff(p),items=[{id:p.id,c:copy(p.draft)},...desiredDelays(p).map(delay=>({id:children(p.id).find(t=>t.delay===delay)?.id||delayLabel(delay)+'（新規）',c:{...copy(p.draft),...shiftLaunch(p.draft,delay)}}))];return{df,items,computed:items.filter(x=>!resultCache.has(cacheKey(x.c))).length,reused:items.filter(x=>resultCache.has(cacheKey(x.c))).length,error:items.map(x=>conditionError(x.c)).find(Boolean)};}
function desiredDelays(t){return state.delayEdits[t.id]??children(t.id).map(c=>c.delay).sort((a,b)=>a-b);}
function delayDiff(t){const desired=desiredDelays(t),existing=children(t.id);return{keep:existing.filter(c=>desired.includes(c.delay)),remove:existing.filter(c=>!desired.includes(c.delay)),add:desired.filter(d=>!existing.some(c=>c.delay===d))};}
const delayChoices=[30,60,90,120,150,180,240,300,360,420,480,540,600,660,720];
const delayLabel=d=>`＋${d/60}時間`;
function openDelays(id){if(bridge.historical)return;const t=tab(id),parent=t?.parentId?tab(t.parentId):t;if(!parent||parent.draft.model==='season')return;choose(parent.id);$('delayDialogTitle').textContent=children(parent.id).length?'遅延列を編集':'遅延列を作る';$('delayError').hidden=true;renderDelays(parent);$('delayDialog').showModal();}
function renderDelays(t){if(!t||t.parentId||t.draft.model==='season')return;const ds=desiredDelays(t),values=[...new Set([...delayChoices,...ds])].sort((a,b)=>a-b);$('delayParent').textContent=`親候補 ${t.id} · ${t.name} / 予定 ${t.draft.date} ${t.draft.time} JST`;$('delayRail').innerHTML=values.map(d=>`<button class="delay-chip ${ds.includes(d)?'selected':''}" data-delay="${d}" aria-pressed="${ds.includes(d)}"><b>${delayLabel(d)}</b><small>${shiftLaunch(t.draft,d).date===t.draft.date?'':'翌日 '}${shiftLaunch(t.draft,d).time} JST${delayChoices.includes(d)?'':' · 既存'}</small></button>`).join('');$$('[data-delay]').forEach(b=>b.onclick=()=>{const d=+b.dataset.delay;state.delayEdits[t.id]=ds.includes(d)?ds.filter(x=>x!==d):[...ds,d].sort((a,b)=>a-b);$('delayError').hidden=true;renderDelays(t);});const plan=delayPlan(t),df=plan.df;$('delayCount').textContent=children(t.id).length?children(t.id).length+'件の子候補':'';$('editDelays').textContent=children(t.id).length?'遅延列を編集':'＋ 遅延列を作る';$('delayPreview').textContent=`作成 ${df.add.length}件 / 維持 ${df.keep.length}件 / 外す ${df.remove.length}件。親と選択した子の草案を、打上げ時刻以外は同じ入力条件へ揃えます。`+(bridge.real?'この操作では計算しません。作成後、条件の計算ボタンから実行します。':`新規計算 ${plan.computed}件 / 結果再利用 ${plan.reused}件。対象：${plan.items.map(x=>x.id).join('・')}。`);$('delayPending').hidden=!dirty(t);$('delayPending').textContent=dirty(t)?`親 ${t.id} の未反映入力を使用：${conditionsText(t.draft)}。${bridge.real?'計算済みの固定結果はそのまま保持します。':'親と遅延列の旧結果を、この条件の結果へ更新します。'}`:'';$('applyDelays').textContent=dirty(t)?'親と遅延列をこの入力で更新':children(t.id).length?'遅延列を更新':'選択した遅延の子候補を作成';$('applyDelays').disabled=!df.add.length&&!df.remove.length&&!dirty(t)&&!children(t.id).some(dirty);}
$('editDelays').onclick=()=>openDelays(state.active);$('cancelDelays').onclick=()=>{$('delayDialog').close();delete state.delayEdits[state.active];renderDelays(activeTab());};$('delayDialog').addEventListener('cancel',()=>{delete state.delayEdits[state.active];renderDelays(activeTab());});
function applyDelays(){const p=activeTab();if(bridge.real){bridge.action('delays',{id:p?.id,delays:desiredDelays(p)});delete state.delayEdits[p?.id];$('delayDialog').close();return;}if(!p||p.parentId)return;const plan=delayPlan(p),df=plan.df;if(plan.error){$('delayError').textContent=plan.error+' 遅延の選択は保ちました。親候補の入力を確認してください。';$('delayError').hidden=false;return;}const execute=()=>{const view={center:map.getCenter(),zoom:map.getZoom()};snapshotRemoval();const removed=df.remove.map(t=>t.id);state.tabs=state.tabs.filter(t=>!removed.includes(t.id));for(const g of state.groups)g.members=g.members.filter(id=>!removed.includes(id));for(const delay of df.add){const c={...copy(p.draft),...shiftLaunch(p.draft,delay)},t=newCase(c,p.name+' '+delayLabel(delay));t.parentId=p.id;t.delay=delay;t.color=p.color;}syncChildren(p);const work=commitResults([p,...children(p.id)]);delete state.delayEdits[p.id];state.collapsed.delete(p.id);$('delayDialog').close();refresh();map.setView(view.center,view.zoom,{animate:false});updateFamilyVisibility();notify(`親と遅延列を更新。計算 ${work.computed}・再利用 ${work.reused} / 子の維持 ${df.keep.length}・追加 ${df.add.length}・除去 ${df.remove.length}。`,true);};const gs=affectedGroups(df.remove.map(t=>t.id));if(gs.length)showDialog('遅延集合の変更',`<p>${df.remove.map(t=>esc(t.id)).join('・')}を系列から外し、${gs.map(g=>esc(g.id)).join('・')}の比較所属からも除きます。</p><p>親と残す子・新しい子を同じ共有入力へ更新します。新規計算${plan.computed}件、再利用${plan.reused}件。</p>`,execute,'集合を変更');else execute();}
$('applyDelays').onclick=applyDelays;
