function rgb(hex){if(!/^#[0-9a-f]{6}$/i.test(hex))throw Error('未対応の比較色: '+hex);return[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)).join(',');}
const comparisonPalette=['#0072B2','#D55E00','#009E73','#CC79A7','#B17C00','#5A9BC8','#7B3294','#A6611A','#018571','#C51B7D','#4D4D4D','#6666CC','#3C6E20','#A8272D','#1C6984','#7D5939'];
function comparisonColor(i){if(comparisonPalette[i])return comparisonPalette[i];const h=(i*137.508)%360,s=.65,l=.38,c=(1-Math.abs(2*l-1))*s,x=c*(1-Math.abs(h/60%2-1)),m=l-c/2,parts=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return'#'+parts.map(v=>Math.round((v+m)*255).toString(16).padStart(2,'0')).join('');}
