const label=photo?'写真':'標準地図',notice=$('mapLoadNotice');notice.hidden=true;$('baseCredit').innerHTML=credit;$('baseStatus').textContent=label+'を取得中…';const update=()=>{if(disposed||generation!==baseGeneration)return;$('baseStatus').textContent=`${label} ${ok}タイル取得 / 失敗${bad}。${photo?'撮影時点は地域により異なります。':'地名・道路・施設を縮尺に応じて表示します。'}`;notice.hidden=bad===0;notice.replaceChildren();if(bad){notice.append(document.createTextNode(`${label}の一部を取得できません (${bad}枚)。入力と計算結果は保持しています。 `));const retry=document.createElement('button');retry.textContent='地図を再試行';retry.onclick=baseLayer;notice.append(retry);}};
