function hasMapView(view){return Array.isArray(view?.map?.center)&&view.map.center.length===2&&view.map.center.every(Number.isFinite)&&Math.abs(view.map.center[0])<=90&&Number.isFinite(view.map.zoom)&&view.map.zoom>=0;}
function restoreMapView(view){
 const incoming=hasMapView(view)?JSON.stringify([view.map.center[0],view.map.center[1],view.map.zoom]):null;
 const changed=incoming!==lastIncomingMapKey;lastIncomingMapKey=incoming;
 // Result GETs sync the same saved view while local pan/fit publication is
 // debounced. Reapplying that old view would undo the user's newer navigation.
 // A newly received saved view, including the first valid one, still wins.
 if(incoming&&changed)map.setView(view.map.center,view.map.zoom,{animate:false});
}
